import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import "../Styles/UserProfile.css";

const CompanyProfile = () => {
  const navigate = useNavigate();

  const [company, setCompany] = useState({});
  const [preview, setPreview] = useState(null);
  const [showCardModal, setShowCardModal] = useState(false);

  // Bank states (same style of student)
  const [bank, setBank] = useState({
    selectedBank: "",
    cardNumber: "",
    cardName: "",
    expiry: "",
    cvv: "",
  });

  // Load company
  useEffect(() => {
    const saved = JSON.parse(localStorage.getItem("loggedUser"));
    if (!saved?.email) {
      navigate("/login");
      return;
    }

    axios
      .get(`http://localhost:3001/company/${saved.email}`)
      .then((res) => {
        setCompany(res.data);

        const b = res.data.bankInfo || {};
        setBank({
          selectedBank: b.bankName || "",
          cardNumber: b.cardNumber || "",
          cardName: b.cardName || "",
          expiry: b.expiry || "",
          cvv: b.cvv || "",
        });
      })
      .catch(() => alert("Failed to load company"));
  }, [navigate]);

  // Upload company image
  const handleImageUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const form = new FormData();
    form.append("file", file);
    form.append("email", company.email);
    form.append("type", "profile");

    try {
      const res = await axios.post(
        "http://localhost:3001/uploadCompanyFile",
        form,
        {
          headers: { "Content-Type": "multipart/form-data" },
        }
      );

      setCompany((prev) => ({ ...prev, profileImage: res.data.fileUrl }));
      setPreview(res.data.fileUrl);

      alert("Profile picture updated!");
    } catch {
      alert("Failed to upload image");
    }
  };

  // Upload license
  const handleLicenseUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const form = new FormData();
    form.append("file", file);
    form.append("email", company.email);
    form.append("type", "license");

    try {
      const res = await axios.post(
        "http://localhost:3001/uploadCompanyFile",
        form,
        {
          headers: { "Content-Type": "multipart/form-data" },
        }
      );

      setCompany((prev) => ({ ...prev, licenseFile: res.data.fileUrl }));
      alert("License uploaded successfully!");
    } catch {
      alert("Failed to upload license");
    }
  };

  // DELETE LICENSE
  const handleDeleteLicense = async () => {
    if (!window.confirm("Delete Business License?")) return;

    try {
      await axios.put("http://localhost:3001/deleteCompanyLicense", {
        email: company.email,
      });

      setCompany((prev) => ({ ...prev, licenseFile: null }));
      alert("License deleted successfully!");
    } catch {
      alert("Failed to delete license.");
    }
  };

  // Save bank info
  const saveCardInfo = async () => {
    try {
      await axios.post(`http://localhost:3001/company/${company.email}/bank`, {
        accountHolder: bank.cardName,
        bankName: bank.selectedBank,
        accountNumber: bank.cardNumber,
        expiry: bank.expiry,
        cvv: bank.cvv,
      });

      alert("Bank info saved!");
      setShowCardModal(false);
    } catch {
      alert("Failed to save bank details");
    }
  };

  // Delete bank card
  const deleteBank = async () => {
    if (!window.confirm("Delete saved bank card?")) return;

    try {
      await axios.post(`http://localhost:3001/company/${company.email}/bank`, {
        accountHolder: "",
        bankName: "",
        accountNumber: "",
        expiry: "",
        cvv: "",
      });

      setBank({
        selectedBank: "",
        cardNumber: "",
        cardName: "",
        expiry: "",
        cvv: "",
      });

      alert("Bank card deleted!");
    } catch {
      alert("Error deleting bank card");
    }
  };

  return (
    <div className="profile-page">
      {/* PROFILE CARD */}
      <div className="profile-card">
        <div className="profile-left">
          <div className="profile-img-container">
            <img
              src={
                preview ||
                company.profileImage ||
                "https://cdn-icons-png.flaticon.com/512/3135/3135768.png"
              }
              className="profile-img"
              alt=""
            />

            <label htmlFor="companyImg" className="upload-circle-C">
              📷
            </label>
            <input
              type="file"
              id="companyImg"
              accept="image/*"
              style={{ display: "none" }}
              onChange={handleImageUpload}
            />
          </div>

          <div>
            <h2 className="profile-name">{company.companyName}</h2>
            <p className="profile-email">{company.email}</p>
            <p className="profile-detail">
              {company.industry} • {company.location}
            </p>
          </div>
        </div>
      </div>

      {/* LICENSE */}
      <div className="payment-box">
        <h3>Business License</h3>

        {company.licenseFile ? (
          <div className="cv-section">
            <p className="cv-success">License Uploaded Successfully</p>

            <div className="cv-actions">
              <a
                href={company.licenseFile}
                target="_blank"
                className="cv-btn view"
              >
                View
              </a>

              <input
                id="licenseReplaceInput"
                type="file"
                accept=".pdf"
                style={{ display: "none" }}
                onChange={handleLicenseUpload}
              />

              <button
                className="cv-btn replace"
                onClick={() =>
                  document.getElementById("licenseReplaceInput").click()
                }
              >
                Replace
              </button>

              <button className="cv-btn delete" onClick={handleDeleteLicense}>
                Delete
              </button>
            </div>
          </div>
        ) : (
          <>
            <input
              id="licenseUpload"
              type="file"
              accept=".pdf"
              style={{ display: "none" }}
              onChange={handleLicenseUpload}
            />

            <label className="upload-cv-btn" htmlFor="licenseUpload">
              Upload License (PDF)
            </label>
          </>
        )}
      </div>

      {/* BANK CARD */}
      <div className="payment-box">
        <h3>Bank / Benefit Card</h3>

        <div className="card-preview">
          <div className="bank-card teal-card">
            <div className="bank-chip"></div>

            <p className="card-number">
              {bank.cardNumber || "XXXX XXXX XXXX XXXX"}
            </p>

            <p className="card-holder">{bank.cardName || "Card Holder"}</p>

            <p className="bank-name-preview">
              {bank.selectedBank || "No Bank Selected"}
            </p>
          </div>
        </div>

        <div className="card-buttons">
          {!bank.cardNumber ? (
            <button
              className="add-card-btn"
              onClick={() => setShowCardModal(true)}
            >
              + Add Card
            </button>
          ) : (
            <>
              <button
                className="edit-card-btn"
                onClick={() => setShowCardModal(true)}
              >
                Edit Card
              </button>
              <button className="delete-card-btn" onClick={deleteBank}>
                Delete Card
              </button>
            </>
          )}
        </div>
      </div>

      {/* MODAL */}
      {showCardModal && (
        <div className="modal-overlay">
          <div className="modal-box">
            <div className="modal-header">
              <h3>Edit Card</h3>
              <button
                className="close-btn"
                onClick={() => setShowCardModal(false)}
              >
                ×
              </button>
            </div>

            <label>Select Bank</label>
            <div className="bank-radio-row">
              <label>
                <input
                  type="radio"
                  value="Bank Muscat"
                  checked={bank.selectedBank === "Bank Muscat"}
                  onChange={(e) =>
                    setBank({ ...bank, selectedBank: e.target.value })
                  }
                />
                Bank Muscat
              </label>

              <label>
                <input
                  type="radio"
                  value="Bank Dhofar"
                  checked={bank.selectedBank === "Bank Dhofar"}
                  onChange={(e) =>
                    setBank({ ...bank, selectedBank: e.target.value })
                  }
                />
                Bank Dhofar
              </label>

              <label>
                <input
                  type="radio"
                  value="NBO"
                  checked={bank.selectedBank === "NBO"}
                  onChange={(e) =>
                    setBank({ ...bank, selectedBank: e.target.value })
                  }
                />
                NBO
              </label>
            </div>

            <label>Card Number</label>
            <input
              className="modal-input"
              value={bank.cardNumber}
              onChange={(e) => {
                let v = e.target.value.replace(/\D/g, "");
                v = v.match(/.{1,4}/g)?.join(" ") || v;
                setBank({ ...bank, cardNumber: v });
              }}
            />

            <label>Cardholder Name</label>
            <input
              className="modal-input"
              value={bank.cardName}
              onChange={(e) => setBank({ ...bank, cardName: e.target.value })}
            />

            <label>Expiration Date</label>
            <input
              type="month"
              className="modal-input"
              value={bank.expiry}
              onChange={(e) => setBank({ ...bank, expiry: e.target.value })}
            />

            <label>CVV</label>
            <input
              type="password"
              maxLength="4"
              className="modal-input"
              value={bank.cvv}
              onChange={(e) => setBank({ ...bank, cvv: e.target.value })}
            />

            <div className="modal-buttons">
              <button className="save-btn" onClick={saveCardInfo}>
                Save
              </button>

              <button
                className="clear-btn"
                onClick={() => setShowCardModal(false)}
              >
                Clear
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CompanyProfile;
